const expected = String($env.WEB_ATTACHMENT_INTERNAL_KEY || '');
const supplied = String($json.headers?.['x-hragent-internal-key'] || '');
if (!expected || supplied !== expected) {
  throw new Error('知识库查询请求未通过内部鉴权');
}

const body = $json.body || $json;
const question = String(body.question || body.chatInput || '').trim();
if (!question) throw new Error('question is required');
return [{ json: { question } }];

const MIN_SCORE = 0.5;
const points = Array.isArray($json.result?.points) ? $json.result.points : [];
const results = points.map((point) => {
  const payload = point.payload || {};
  const metadata = payload.metadata || {};
  const location = String(metadata.filter_by_filename || payload.filter_by_filename || '').trim();
  const source = location.split('/').pop() || '\u672a\u547d\u540d\u6587\u4ef6';
  const content = String(payload.content || payload.pageContent || payload.text || '').trim();
  const score = Number(point.score);
  return { source, score, content };
}).filter((item) => item.content && Number.isFinite(item.score) && item.score >= MIN_SCORE);

return [{
  json: {
    success: true,
    found: results.length,
    sources: results.map((item) => item.source),
    results,
    context: results.map((item) => '\u6765\u6e90\u6587\u4ef6\uff1a' + item.source + '\\n' + item.content).join('\\n\\n'),
    minScore: MIN_SCORE,
    message: results.length ? '\u5df2\u627e\u5230\u76f8\u5173\u5236\u5ea6' : '\u5f53\u524d\u77e5\u8bc6\u5e93\u6ca1\u6709\u76f8\u5173\u5236\u5ea6',
  },
}];

const expected = String($env.WEB_ATTACHMENT_INTERNAL_KEY || '');
const supplied = String($json.headers?.['x-hragent-internal-key'] || '');
if (!expected || supplied !== expected) {
  throw new Error('知识库目录请求未通过内部鉴权');
}

const body = $json.body || $json;
return [{ json: { filename: String(body.filename || '').trim() } }];

const requested = String($('Normalize Knowledge File Request').first().json.filename || '').trim();
const requestedBase = requested.replace(/\\/g, '/').split('/').pop().toLocaleLowerCase('zh-CN');
const points = Array.isArray($json.result?.points) ? $json.result.points : [];
const names = points.map((point) => {
  const payload = point.payload || {};
  const metadata = payload.metadata || {};
  const location = String(metadata.filter_by_filename || payload.filter_by_filename || '').trim();
  return location.replace(/\\/g, '/').split('/').pop();
}).filter(Boolean);
const files = [...new Set(names)].sort((a, b) => a.localeCompare(b, 'zh-CN'));
const exists = requested
  ? files.some((name) => name.toLocaleLowerCase('zh-CN') === requestedBase)
  : null;
return [{ json: {
  success: true,
  mode: requested ? 'exists' : 'list',
  requestedFilename: requested,
  exists,
  count: files.length,
  files,
  message: requested
    ? (exists ? '知识库中存在文件：' + requested : '知识库中不存在文件：' + requested)
    : '知识库中共有 ' + files.length + ' 个文件',
} }];
